#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# The wizard library lives in wizard-lib.sh: do not hand-edit it. Author the
# per-step stages below the marker.

set -euo pipefail

# The shared wizard library: prompts, stages and .env handling.
# shellcheck source=wizard-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/wizard-lib.sh"

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=12

# Run from the repo root. Captured values go to a gitignored file, not a .env.
cd "$(git rev-parse --show-toplevel)"
ENV_FILE="dist/curseforge-release.env"
mkdir -p dist
PY=""
for candidate in .venv/Scripts/python.exe .venv/Scripts/python .venv/bin/python; do
  [[ -f "$candidate" ]] && { PY="$candidate"; break; }
done
if [[ -z "$PY" ]]; then
  warn "No .venv found. Create it first: py -3.14 -m venv .venv"
  exit 1
fi
# Git Bash mounts drive C at /c; WSL mounts it at /mnt/c.
if [[ -z "${WOW_ROOT:-}" ]]; then
  for drive in /c /mnt/c; do
    WOW_ROOT="$drive/Program Files (x86)/World of Warcraft/_forever_"
    [[ -d "$WOW_ROOT" ]] && break
  done
fi
SHOTS_DIR="$WOW_ROOT/Screenshots"
OUT_DIR="docs/curseforge/screenshots"
VERSION=$(sed -n 's/^## Version: //p' AzerothLedger/AzerothLedger.toc | tr -d '\r')
ZIP="dist/AzerothLedger-$VERSION.zip"

# copy_text FILE puts a file on the clipboard, if a clipboard tool exists.
copy_text() {
  if command -v clip.exe >/dev/null 2>&1; then clip.exe < "$1"
  elif command -v pbcopy >/dev/null 2>&1; then pbcopy < "$1"
  elif command -v xclip  >/dev/null 2>&1; then xclip -selection clipboard < "$1"
  else warn "no clipboard tool: open $1 and copy it by hand"; return; fi
  printf '  %s✓ copied%s %s to the clipboard\n' "$GREEN" "$RESET" "$1"
}

# shot NAME waits for a new screenshot in the client's folder and saves it as NAME.
shot() {
  local name="$1" marker newest
  marker=$(mktemp)
  mkdir -p "$OUT_DIR"
  while true; do
    step "Press Print Screen in-game once the view looks right."
    pause "Press Enter here after taking the screenshot"
    newest=$(find "$SHOTS_DIR" -maxdepth 1 -type f \( -iname '*.jpg' -o -iname '*.png' -o -iname '*.tga' \) \
      -newer "$marker" -printf '%T@ %p\n' 2>/dev/null | sort -rn | head -n1 | cut -d' ' -f2- || true)
    if [[ -z "$newest" ]]; then
      warn "no new screenshot in $SHOTS_DIR yet, so take it again"
      continue
    fi
    if [[ "${newest,,}" == *.tga ]]; then
      warn "that one is a .tga, which CurseForge won't accept."
      note "Run /console screenshotFormat jpeg in-game, then take it again."
      continue
    fi
    cp "$newest" "$OUT_DIR/$name.${newest##*.}"
    printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$OUT_DIR/$name.${newest##*.}"
    confirm "Keep this one? (No takes it again)" && break
  done
  rm -f "$marker"
}

# An update once the project exists: skip the screenshots and project setup.
CF_PROJECT_ID=$(_existing CF_PROJECT_ID || true)
CF_PROJECT_URL=$(_existing CF_PROJECT_URL || true)
UPDATE=0
if [[ -n "$CF_PROJECT_ID" ]]; then
  UPDATE=1
  TOTAL_STAGES=4
fi

if (( UPDATE )); then
  banner "Azeroth Ledger $VERSION → CurseForge (update to project $CF_PROJECT_ID)"
else
  banner "Azeroth Ledger $VERSION → CurseForge"
fi

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Release from an up-to-date main"
say "The release must be built from merged code on main."
git fetch --quiet origin
step "Current branch: $(git branch --show-current)"
step "Uncommitted changes: $(git status --porcelain -- . ':!scripts/curseforge-release.sh' | wc -l | tr -d ' ') file(s)"
step "TOC version: $VERSION"
while [[ "$(git branch --show-current)" != "main" || -n "$(git status --porcelain -- . ':!scripts/curseforge-release.sh')" \
        || "$(git rev-parse HEAD)" != "$(git rev-parse origin/main)" ]]; do
  warn "Merge your open PRs first (including the version bump), then in another terminal run:"
  note "    git switch main && git pull --ff-only"
  pause "Press Enter once you're on a clean main that matches origin/main"
  git fetch --quiet origin
done
VERSION=$(sed -n 's/^## Version: //p' AzerothLedger/AzerothLedger.toc | tr -d '\r')
ZIP="dist/AzerothLedger-$VERSION.zip"
printf '  %s✓%s clean main at %s, version %s\n' "$GREEN" "$RESET" "$(git rev-parse --short HEAD)" "$VERSION"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Checks, package, and install into Forever"
say "Running every CI check, building the release zip, and installing into the client."
"$PY" tools/verify.py
"$PY" tools/package.py --output "$ZIP"
"$PY" tools/install_local.py
"$PY" tools/install_local.py --verify-only
printf '  %s✓%s built %s\n' "$GREEN" "$RESET" "$ZIP"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "In-client tests"
step "Start (or /reload) the Forever client and log in to a character."
step "Open WoWUnit and run every AzerothLedger group, including AzerothLedgerCollection,"
note "  AzerothLedgerExchange, AzerothLedgerForever, AzerothLedgerJournal,"
note "  AzerothLedgerPresentation, AzerothLedgerVendor and AzerothLedgerPerformance."
step "Watch for Lua error popups while you do."
ask WOW_BUILD "Client build (shown on the login screen, bottom left):"
ask WOW_LOCALE "Client locale (e.g. enUS):"
ask WOWUNIT_RESULT "WoWUnit result (e.g. all passed, or which failed):"
ask LUA_ERRORS "Lua errors seen (none, or paste them):"
write_env WOW_BUILD "$WOW_BUILD"
write_env WOW_LOCALE "$WOW_LOCALE"
write_env WOWUNIT_RESULT "$WOWUNIT_RESULT"
write_env LUA_ERRORS "$LUA_ERRORS"
if ! confirm "Did every group pass with no Lua errors?"; then
  warn "Fix the failures before releasing. Your answers are saved in $ENV_FILE."
  exit 1
fi

if (( ! UPDATE )); then

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Screenshot 1 of 6: the Collection"
say "These go in the CurseForge gallery. Use a character with a full, varied Collection."
note "Hide anything you don't want public, like guild chat or whispers."
note "Don't press Alt+Z: it hides the addon too."
step "Type /al and pick a busy category in Account view so the list is full of item icons."
shot "01-collection"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Screenshot 2 of 6: an item's history"
step "In the book, select an interesting item, like one Looted from a named creature or a crafted one,"
step "so the detail panel shows its Seen/Looted/Obtained dates, Total gained and Source."
shot "02-item-detail"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Screenshot 3 of 6: the Journal"
step "Open the Journal and select an entry so it shows who was involved and where the item came from."
shot "03-journal"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Screenshot 4 of 6: the item tooltip"
step "Close the book and hover over an item in your bags to show the Azeroth Ledger tooltip lines."
shot "04-tooltip"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Screenshot 5 of 6: a discovery notification"
step "Go to Esc → Options → AddOns → Azeroth Ledger → Notifications and click Preview notification."
step "Close the settings so the notification shows over the game world."
note "It lasts five seconds by default; raise Duration first if you need longer."
shot "05-notification"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Screenshot 6 of 6: themes"
step "Under Appearance, pick a theme other than Classic Gold (Arcane Violet or Parchment look good)."
step "Then open the book with /al so it shows next to the settings."
shot "06-themes"
note "Set the theme back afterwards if you like."
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Create the CurseForge project"
say "Sign in to CurseForge first, or create an account if you don't have one."
open_url "https://authors.curseforge.com/#/projects/create/choose-game"
step "Choose World of Warcraft, then the Addons class."
step "Project name:  Azeroth Ledger"
step "Summary:       Remembers the items on all your characters and how you got them."
step "Main category: Bags & Inventory (add other fitting categories if offered)."
step "License:       All Rights Reserved"
step "Logo/avatar:   upload docs/curseforge/logo.png"
copy_text docs/curseforge/description.md
step "Description: if the editor offers Markdown, choose it and paste the clipboard."
note "  Otherwise, open docs/curseforge/description.md in a Markdown preview and copy the rendered text."
step "Create the project."
ask CF_PROJECT_URL "Paste the project's public URL (curseforge.com/wow/addons/...):"
ask CF_PROJECT_ID "Paste the Project ID (shown in the About Project box or project settings):"
write_env CF_PROJECT_URL "$CF_PROJECT_URL"
write_env CF_PROJECT_ID "$CF_PROJECT_ID"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Upload the screenshots"
step "On the project in the authors console, open Images (or Gallery) and upload."
step "Add these in order, each with a short title:"
for f in "$OUT_DIR"/*; do note "    $f"; done
note "  Suggested titles: The Collection · Item history · The Journal · Tooltip · Discovery notification · Themes"
step "Make 01-collection the featured image if the page lets you."
pause "Press Enter once the gallery is uploaded"

fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Upload the release file"
if ! grep -q "^## $VERSION\$" CHANGELOG.md; then
  warn "CHANGELOG.md has no '## $VERSION' section. Add one, merge it, then run this again."
  exit 1
fi
NOTES="dist/changelog-$VERSION.md"
awk -v v="$VERSION" '/^## /{p=($2==v); next} p' CHANGELOG.md | sed '/./,$!d' > "$NOTES"
open_url "https://authors.curseforge.com/#/projects"
step "Open Azeroth Ledger, then its Files tab, and choose Upload File."
step "File:          $ZIP"
step "Display name:  Azeroth Ledger $VERSION"
step "Release type:  Release"
step "Game version:  the Forever flavor version that matches interface 16001."
warn "If no Forever game version is listed, stop. Don't upload under Classic or Retail."
copy_text "$NOTES"
step "Changelog:     paste the clipboard (from CHANGELOG.md, choose Markdown if offered):"
while IFS= read -r line; do note "    $line"; done < "$NOTES"
if confirm "Submit the file now? It goes to CurseForge moderation and can't be undone."; then
  step "Click Upload/Submit in the browser."
  pause "Press Enter once CurseForge shows the file as uploaded"
  write_env CF_RELEASED_VERSION "$VERSION"
  note "CurseForge reviews new projects and files before they go public; watch your email."
else
  SKIPPED+=("Upload $ZIP to $CF_PROJECT_URL")
fi

finish
note "Screenshots: $OUT_DIR · logo: docs/curseforge/logo.png · values: $ENV_FILE"
note "Once approved, add the project link to README.md."
}

run_wizard "$@"; exit
